import Joi from "joi";
import { locationFields, locationSchema } from "../auth/auth.validation";

const confirmedLocationSchema = Joi.object({
  ...locationFields,
  street1: locationFields.street1.required(),
  point: locationFields.point.strict().required(),
  pointSource: Joi.string().valid("device", "search", "pin").required(),
  accuracyMeters: Joi.when("pointSource", {
    is: "device",
    then: Joi.number().strict().min(0).max(5000).required(),
    otherwise: Joi.forbidden(),
  }),
  // These describe the saved confirmation and are always generated by the server.
  confirmedAt: Joi.forbidden(),
  formattedAddress: Joi.forbidden(),
}).with("lgaCode", "lga");

export const updateLocationSchema = Joi.object({
  confirmed: Joi.boolean().strict().valid(true),
  location: Joi.when("confirmed", {
    is: Joi.valid(true).required(),
    then: confirmedLocationSchema.required(),
    otherwise: locationSchema.required(),
  }),
});
